def apply_overrides(config: ExperimentConfig, args: argparse.Namespace) -> ExperimentConfig:
    updates: dict[str, Any] = {}
    for field_name in ("device", "epochs", "batch_size", "eval_batch_size", "num_workers"):
        value = getattr(args, field_name)
        if value is not None:
            updates[field_name] = value

    if args.smoke:
        updates["epochs"] = config.smoke_epochs
        updates["num_workers"] = config.smoke_num_workers
        updates["persistent_workers"] = False
        updates["lr_range_steps"] = config.smoke_lr_range_steps

    return replace(config, **updates)


def merge_checkpoint_config(
    config: ExperimentConfig,
    checkpoint_config: dict[str, Any] | None,
) -> ExperimentConfig:
    if not checkpoint_config:
        return config

    valid_fields = {field.name for field in fields(ExperimentConfig)}
    updates = {key: value for key, value in checkpoint_config.items() if key in valid_fields}
    if not updates:
        return config
    return replace(config, **updates)


def set_random_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)


def resolve_device(config: ExperimentConfig) -> torch.device:
    requested = config.device.lower()
    if requested == "cuda":
        if torch.cuda.is_available():
            return torch.device("cuda")
        if config.allow_cpu_fallback:
            return torch.device("cpu")
        raise RuntimeError("CUDA requested but not available.")
    return torch.device(requested)


def prepare_output_dir(config: ExperimentConfig, smoke: bool) -> Path:
    output_root = REPO_ROOT / config.output_dir
    output_root.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(UTC).strftime("%Y-%m-%d_%H-%M-%S")
    run_name = f"{timestamp}_smoke" if smoke else timestamp
    run_dir = output_root / run_name
    run_dir.mkdir(parents=True, exist_ok=False)
    return run_dir


def save_json(path: Path, payload: dict[str, Any]) -> None:
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def load_sequence_store(
    dataset_path: Path,
    config: ExperimentConfig,
    sequence_limit: int | None,
) -> SequenceStore:
    frame = load_lob_frame(dataset_path, select_columns=SEQUENCE_SELECT_COLUMNS)
    frame = limit_frame_to_sequences(frame=frame, n_sequences=sequence_limit, seed=config.seed)
    return build_sequence_store(frame=frame, feature_columns=RAW_FEATURE_COLUMNS)


def compute_sequence_activity_scores(store: SequenceStore) -> np.ndarray:
    targets = np.abs(store.targets[:, :, T1_INDEX]).astype(np.float64, copy=False)
    mask = store.need_prediction.astype(np.float64, copy=False)
    counts = np.maximum(mask.sum(axis=1), 1.0)
    return ((targets * mask).sum(axis=1) / counts).astype(np.float32, copy=False)


def build_tail_sampling_weights(
    activity_scores: np.ndarray,
    target_fraction: float,
    active_quantile: float,
) -> tuple[np.ndarray, dict[str, float]]:
    if not 0.0 < target_fraction < 1.0:
        raise ValueError("target_fraction must be in (0, 1).")
    if not 0.0 < active_quantile < 1.0:
        raise ValueError("active_quantile must be in (0, 1).")

    threshold = float(np.quantile(activity_scores, active_quantile))
    active_mask = activity_scores > threshold
    observed_fraction = float(np.mean(active_mask))
    active_count = int(active_mask.sum())
    total_count = int(activity_scores.shape[0])
    extra_active_samples = 0
    effective_fraction = observed_fraction
    if 0 < active_count < total_count and observed_fraction < target_fraction:
        numerator = (target_fraction * total_count) - active_count
        denominator = max(1.0 - target_fraction, 1e-8)
        extra_active_samples = int(math.ceil(max(numerator / denominator, 0.0)))
        effective_fraction = float((active_count + extra_active_samples) / (total_count + extra_active_samples))

    summary = {
        "active_threshold": threshold,
        "observed_active_fraction": observed_fraction,
        "target_active_fraction": float(target_fraction),
        "active_sequences": float(active_count),
        "extra_active_samples_per_epoch": float(extra_active_samples),
        "effective_active_fraction_per_epoch": effective_fraction,
    }
    return active_mask.astype(np.bool_, copy=False), summary


class FullCoverageTailSampler(Sampler[int]):
    """Sampler that covers all sequences once per epoch and appends extra active duplicates."""

    def __init__(
        self,
        dataset_size: int,
        active_mask: np.ndarray,
        extra_active_samples: int,
        seed: int,
    ) -> None:
        if dataset_size <= 0:
            raise ValueError("dataset_size must be > 0.")
        if active_mask.shape != (dataset_size,):
            raise ValueError("active_mask must have shape [dataset_size].")
        if extra_active_samples < 0:
            raise ValueError("extra_active_samples must be >= 0.")

        self.dataset_size = int(dataset_size)
        self.base_indices = np.arange(dataset_size, dtype=np.int64)
        self.active_indices = np.flatnonzero(active_mask).astype(np.int64, copy=False)
        self.extra_active_samples = int(extra_active_samples)
        self.seed = int(seed)
        self._epoch = 0

    def __iter__(self):
        rng = np.random.default_rng(self.seed + self._epoch)
        self._epoch += 1

